// @generated by:gauntlet run:godseye-local-database
import { randomUUID } from "node:crypto";
import { describe, expect, it } from "vitest";
import {
  AdmitDatabase,
  DatabaseOverview,
  DatabaseProfile,
  PrepareDatabase,
} from "../packages/contracts/src/database.js";
import {
  compileDatabaseProfile,
  renderDatabaseHba,
  renderDatabaseSettings,
} from "../packages/core/src/database-policy.js";

import { fixtureProfile } from "./pg-helpers.js";

const scope = () => ({
  allocationId: randomUUID(),
  projectId: randomUUID(),
  environmentId: randomUUID(),
});
const binding = {
  ipv4Cidr: "10.40.0.0/24",
  ipv6Cidr: "fd40:1234:5678::/64",
  bootstrapRole: "bootstrap_admin",
};

describe("independent PostgreSQL profile authority", () => {
  it.each([
    { engine: "sqlite" },
    { majorVersion: 17 },
    { maxConnections: 0 },
    { maxConnections: 257 },
    { memoryMiB: Number.POSITIVE_INFINITY },
    { dataGiB: 0 },
    { walGiB: 129 },
    { temporaryMiB: 0 },
    { cpuMilliCores: 100.5 },
    { memoryMiB: Number.NaN },
  ])("T-AC-28 rejects an unsupported or unbounded profile %j", (changed) => {
    expect(DatabaseProfile.safeParse({ ...fixtureProfile, ...changed }).success).toBe(false);
  });

  it.each([
    { sql: "SELECT 1" },
    { settings: { shared_preload_libraries: "caller" } },
    { dataDirectory: "/host/postgres" },
    { walDirectory: "/host/wal" },
    { host: "caller.invalid" },
    { providerId: "caller-provider" },
    { roles: { api: { superuser: true } } },
    { material: "caller-material" },
  ])("T-AC-28 T-AC-31 rejects caller execution escape fields %j", (changed) => {
    expect(DatabaseProfile.safeParse({ ...fixtureProfile, ...changed }).success).toBe(false);
  });

  it("T-AC-28 derives distinct data/WAL and role mappings for independently allocated cells", () => {
    const first = compileDatabaseProfile(fixtureProfile, scope());
    const second = compileDatabaseProfile(fixtureProfile, scope());

    expect(first.dataVolume).not.toBe(first.walVolume);
    expect(
      new Set([first.dataVolume, first.walVolume, second.dataVolume, second.walVolume]).size,
    ).toBe(4);
    expect(first.applicationDatabase).not.toBe(first.workflowDatabase);
    const names = [...Object.values(first.roles), ...Object.values(second.roles)].map(
      (role) => role.name,
    );
    expect(new Set(names).size).toBe(names.length);
    expect(names.every((name) => /^[a-z_][a-z0-9_]{0,62}$/.test(name))).toBe(true);
    expect(first.configurationHash).not.toBe(second.configurationHash);
  });

  it("T-AC-28 fixes profile integrity independently of mutable caller input", () => {
    const input = structuredClone(fixtureProfile);
    const identity = scope();
    const first = compileDatabaseProfile(input, identity);
    const same = compileDatabaseProfile(structuredClone(input), identity);
    input.maxConnections += 1;

    expect(first).toEqual(same);
    expect(first.limits.maxConnections).toBe(fixtureProfile.maxConnections);
    expect(compileDatabaseProfile(input, identity).configurationHash).not.toBe(
      first.configurationHash,
    );
    expect(
      compileDatabaseProfile(fixtureProfile, { ...identity, environmentId: randomUUID() })
        .configurationHash,
    ).not.toBe(first.configurationHash);
  });

  it("T-AC-30 bounds all role connections within the finite server budget", () => {
    for (let maxConnections = 32; maxConnections <= 256; maxConnections += 1) {
      const compiled = compileDatabaseProfile({ ...fixtureProfile, maxConnections }, scope());
      const total = Object.values(compiled.roles).reduce((sum, role) => sum + role.connections, 0);
      expect(total).toBeLessThanOrEqual(maxConnections - 3);
      expect(
        Object.values(compiled.roles).every(
          (role) => Number.isSafeInteger(role.connections) && role.connections > 0,
        ),
      ).toBe(true);
    }
  });

  it("T-AC-30 T-AC-31 fixes TLS, SCRAM, temporary/WAL limits and disables replication capacity", () => {
    const settings = renderDatabaseSettings(compileDatabaseProfile(fixtureProfile, scope()));

    expect(settings).toMatchObject({
      ssl: "on",
      ssl_min_protocol_version: "TLSv1.2",
      password_encryption: "scram-sha-256",
      max_connections: String(fixtureProfile.maxConnections),
      max_replication_slots: "0",
      max_wal_senders: "0",
    });
    expect(settings.temp_file_limit).toBe(`${fixtureProfile.temporaryMiB}MB`);
    expect(Number.parseInt(settings.max_wal_size ?? "", 10)).toBeLessThanOrEqual(
      fixtureProfile.walGiB * 1024,
    );
  });

  it("T-AC-28 refuses an altered compiled authority before rendering settings or HBA", () => {
    const compiled = compileDatabaseProfile(fixtureProfile, scope());
    compiled.dataVolume = "foreign-volume";

    expect(() => renderDatabaseSettings(compiled)).toThrow();
    expect(() => renderDatabaseHba(compiled, binding)).toThrow();
  });

  it("T-AC-31 restricts each runtime role to its own database over TLS and rejects all fallback traffic", () => {
    const compiled = compileDatabaseProfile(fixtureProfile, scope());
    const rules = renderDatabaseHba(compiled, binding).trim().split("\n");

    expect(rules.slice(-2)).toEqual(["host all all 0.0.0.0/0 reject", "host all all ::/0 reject"]);
    expect(rules).toContain("local all all reject");
    for (const [role, policy] of Object.entries(compiled.roles)) {
      const matches = rules.filter((line) => line.split(" ")[2] === policy.name);
      const database = role.startsWith("workflow")
        ? compiled.workflowDatabase
        : compiled.applicationDatabase;
      const databases =
        role === "backup" ? [compiled.applicationDatabase, compiled.workflowDatabase] : [database];
      expect(matches).toEqual(
        [binding.ipv4Cidr, binding.ipv6Cidr].flatMap((cidr) =>
          databases.map((db) => `hostssl ${db} ${policy.name} ${cidr} scram-sha-256`),
        ),
      );
    }
    expect(rules.some((line) => /\b(trust|md5|password)\b/.test(line))).toBe(false);
  });

  it.each([
    { ipv4Cidr: "0.0.0.0/0" },
    { ipv4Cidr: "203.0.113.2/32" },
    { ipv6Cidr: "::/0" },
    { ipv4Cidr: "10.999.0.0/24" },
    { ipv4Cidr: "10.0.0.0/0" },
    { ipv6Cidr: "fd40::::/64" },
    { bootstrapRole: "admin\nhost all all all trust" },
  ])("T-AC-31 rejects public or injected private HBA bindings %j", (changed) => {
    const compiled = compileDatabaseProfile(fixtureProfile, scope());
    expect(() => renderDatabaseHba(compiled, { ...binding, ...changed })).toThrow();
  });

  it("T-AC-29 requires exact preparation hash and bounded lifecycle intents", () => {
    const admitted = {
      preparationId: randomUUID(),
      expectedHash: "a".repeat(64),
      intent: "provision",
    };
    expect(AdmitDatabase.safeParse(admitted).success).toBe(true);
    for (const changed of [
      { expectedHash: "caller" },
      { intent: "delete" },
      { allocationId: randomUUID() },
      { actor: { kind: "owner" } },
    ]) {
      expect(AdmitDatabase.safeParse({ ...admitted, ...changed }).success).toBe(false);
    }
    const preparation = {
      projectId: randomUUID(),
      environmentId: randomUUID(),
      expectedProjectRevision: 0,
      expectedEnvironmentRevision: 0,
      profile: fixtureProfile,
    };
    expect(PrepareDatabase.safeParse(preparation).success).toBe(true);
    expect(
      PrepareDatabase.safeParse({ ...preparation, expectedEnvironmentRevision: undefined }).success,
    ).toBe(false);
  });

  it("T-AC-31 rejects material-bearing owner DTOs rather than silently stripping fields", () => {
    const overview = {
      execution: "unconfigured",
      backup: "unqualified",
      restore: "unqualified",
      rotation: "unqualified",
      preparations: [],
      allocations: [],
    };
    expect(DatabaseOverview.safeParse(overview).success).toBe(true);
    for (const changed of [
      { connectionString: "postgresql://private" },
      { material: "private" },
      { sql: "SELECT 1" },
    ]) {
      expect(DatabaseOverview.safeParse({ ...overview, ...changed }).success).toBe(false);
    }
  });
});
